// Package legal holds the core domain of the Ethiopian legal corpus: documents,
// their versions, the articles inside a version, and the chunks that retrieval
// runs over.
//
// It sits at the bottom of the dependency graph and imports no sibling package.
// Everything else — search, rag, citations, ingestion — depends on it, and it
// depends on nothing but the standard library.
package legal

import "time"

// Identifiers are UUIDs generated by Postgres. They are distinct named types
// rather than bare strings because a single citation carries four of them at
// once, and passing an article ID where a chunk ID belongs is the kind of bug
// that type-checks, runs, and returns the wrong law.
type (
	DocumentID string
	VersionID  string
	ArticleID  string
	ChunkID    string
)

// Language of a document's text. The corpus is bilingual from the start.
type Language string

const (
	LanguageEnglish Language = "en"
	LanguageAmharic Language = "am"
)

// Valid reports whether l is a language the corpus supports.
func (l Language) Valid() bool {
	switch l {
	case LanguageEnglish, LanguageAmharic:
		return true
	default:
		return false
	}
}

// FTSConfig returns the Postgres text-search configuration to index this
// language under.
//
// Postgres ships no Amharic dictionary — no stemmer, no stop words — so
// Amharic indexes under "simple", which tokenises without linguistic
// processing. Amharic fuzzy matching therefore leans on the trigram index
// rather than on tsquery, and Amharic recall leans harder on vector search.
func (l Language) FTSConfig() string {
	if l == LanguageEnglish {
		return "english"
	}
	return "simple"
}

// DocType is the kind of legal instrument.
type DocType string

const (
	DocTypeProclamation DocType = "proclamation"
	DocTypeRegulation   DocType = "regulation"
	DocTypeDirective    DocType = "directive"
	DocTypeCode         DocType = "code"
	DocTypeOther        DocType = "other"
)

// VersionStatus tracks a version through the ingestion workflow. Only
// published versions are visible to retrieval.
type VersionStatus string

const (
	VersionDraft      VersionStatus = "draft"
	VersionPublished  VersionStatus = "published"
	VersionSuperseded VersionStatus = "superseded"
)

// StructureConfidence records whether an article was recovered from the
// document's real legal structure or fell back to fixed-size windows. Low
// confidence is carried all the way to retrieval so degraded chunks can be
// measured separately rather than quietly polluting the corpus.
type StructureConfidence string

const (
	StructureHigh StructureConfidence = "high"
	StructureLow  StructureConfidence = "low"
)

// Document is a legal instrument, independent of any particular version of its
// text. Amendments produce new Versions; a Document row is never rewritten.
type Document struct {
	ID               DocumentID
	Title            string
	DocType          DocType
	LegalDomain      string
	IssuingAuthority string
	PublicationDate  *time.Time
	EffectiveDate    *time.Time
	Language         Language
	SourceURL        string // official source, retained for verification only
	StorageKey       string // key of the original PDF in object storage
	CreatedAt        time.Time
}

// Version is one published state of a Document's text. Versions are additive:
// an amendment inserts a new row and marks the old one superseded. Nothing is
// updated in place, so an answer can always name the version it relied on.
type Version struct {
	ID            VersionID
	DocumentID    DocumentID
	Label         string // e.g. "2021", "as amended 2024"
	EffectiveFrom *time.Time
	RepealedAt    *time.Time
	Status        VersionStatus
	PublishedAt   *time.Time

	// Provenance of the artifact this version was parsed from. It lives here
	// rather than on Document because a document accumulates versions from
	// different files, and ingestion reuses an existing document row without
	// rewriting it — so a document-level source URL only ever describes the
	// first version ingested.
	//
	// SourceChecksum is the sha256 of that file, and is unique across the whole
	// corpus: the same bytes are never ingested twice.
	SourceChecksum string
	SourceURL      string
	StorageKey     string
}

// InForceAt reports whether this version was in force on the given date.
//
// Effectiveness is a deterministic date comparison in Go and SQL — never a
// judgement delegated to the model. An unknown EffectiveFrom is treated as
// permissive (in force) rather than excluding the version, because silently
// dropping a provision is worse than surfacing one whose date is unverified;
// the answer states which version it used.
func (v Version) InForceAt(t time.Time) bool {
	if v.EffectiveFrom != nil && t.Before(*v.EffectiveFrom) {
		return false
	}
	if v.RepealedAt != nil && !t.Before(*v.RepealedAt) {
		return false
	}
	return true
}

// Live reports whether the version is published and in force at t. This is the
// full predicate retrieval filters on.
func (v Version) Live(t time.Time) bool {
	return v.Status == VersionPublished && v.InForceAt(t)
}

// Article is one numbered provision within a version — the unit citations
// point at, and the default unit of chunking.
type Article struct {
	ID         ArticleID
	VersionID  VersionID
	DocumentID DocumentID

	// Number is normalised to Arabic numerals; NumberRaw preserves the form as
	// printed, which in Amharic documents is often Ge'ez ("፵፭"). Both are kept
	// so that a user searching either way finds the article.
	Number    string
	NumberRaw string

	Title       string
	Chapter     string
	SectionPath []string // e.g. ["Book II", "Title V", "Chapter 3"]
	Text        string
	Ordinal     int // position within the version, for stable ordering

	// Span in the extracted source text, so the UI can highlight the provision
	// in the original document.
	PageNo    int
	CharStart int
	CharEnd   int

	StructureConfidence StructureConfidence
}

// Chunk is a retrievable segment. By default one chunk is one article; long
// articles split at sub-article boundaries and keep the parent link.
type Chunk struct {
	ID         ChunkID
	ArticleID  ArticleID
	VersionID  VersionID
	DocumentID DocumentID
	Language   Language

	// Text is the raw span, and is what the user is shown.
	//
	// EmbedText is the contextualised form that is embedded and full-text
	// indexed: document title, chapter, and article number prepended to the
	// span. Without that header an isolated "(2) The period shall be thirty
	// days." is unretrievable, because nothing in it says which period, under
	// which law.
	Text      string
	EmbedText string

	TokenCount int
	Ordinal    int
}
